update country_flag_history set label_fr = 'Yémen du Sud (1967-1990)', label_en = 'South Yemen (1967–1990)', notes_fr = 'Le Yémen du Sud marxiste ajoute au tricolore rouge-blanc-noir un triangle bleu clair frappé d''une étoile rouge ; il s''unit au Nord le 22 mai 1990.', notes_en = 'Marxist South Yemen added a light-blue triangle with a red star to the red-white-black tricolour; it united with the North on 22 May 1990.', image_url = '/flags/history/ye-0000.svg' where id = 2290 and iso_code = 'ye';
