insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ye', '/flags/history/ye-1927.svg', '1927-01-01', '1962-09-26', 'Royaume mutawakkilite du Yémen', 'Mutawakkilite Kingdom of Yemen', 'Royaume des imams zaydites : drapeau rouge au sabre blanc et aux cinq étoiles, pour les cinq piliers de l''islam.', 'The kingdom of the Zaydi imams: a red flag with a white sword and five stars, for the five pillars of Islam.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ye', '/flags/history/ye-1937.svg', '1937-04-01', '1963-01-18', 'Colonie d''Aden', 'Aden Colony', 'Blue Ensign de la colonie d''Aden, escale clé de la route des Indes après l''ouverture du canal de Suez.', 'Blue Ensign of Aden Colony, a key stop on the route to India after the Suez Canal opened.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ye', '/flags/history/ye-1962.svg', '1962-09-26', '1990-05-22', 'République arabe du Yémen (Nord)', 'Yemen Arab Republic (North)', 'Après la révolution de 1962, la République arabe du Yémen adopte le tricolore rouge-blanc-noir frappé d''une étoile verte.', 'After the 1962 revolution, the Yemen Arab Republic adopted the red-white-black tricolour with a green star.');
